namespace NuvTools.Security.Captcha;

/// <summary>
/// Wire contract shared by the client that produces a CAPTCHA token and the server that validates it.
/// </summary>
/// <remarks>
/// These values are part of the HTTP contract between the two sides. Changing any of them requires
/// deploying client and server together.
/// </remarks>
public static class CaptchaDefaults
{
    /// <summary>Request header carrying the token generated by the CAPTCHA provider.</summary>
    public const string TokenHeader = "X-Captcha-Token";

    /// <summary>
    /// Request header carrying the token mode: <see cref="ModeScore"/> or <see cref="ModeCheckbox"/>.
    /// </summary>
    public const string ModeHeader = "X-Captcha-Mode";

    /// <summary>
    /// Response header set to <c>true</c> when the client must escalate to the checkbox challenge.
    /// Redundant with <see cref="StepUpMarker"/>, for direct reading.
    /// </summary>
    public const string StepUpHeader = "X-Captcha-Stepup";

    /// <summary>
    /// Marker returned as the failure message title when the risk score is too low and the client
    /// must present the checkbox challenge. The client matches on this value.
    /// </summary>
    public const string StepUpMarker = "captcha-stepup";

    /// <summary>Invisible token obtained from the score key. Default mode for every submission.</summary>
    public const string ModeScore = "score";

    /// <summary>Token obtained from the checkbox key, used as the step-up challenge.</summary>
    public const string ModeCheckbox = "checkbox";
}
